// ---------- Survey definition ----------
const COH=[["hosp","Hotel/Unterkunft oder Service-Betreiber","Hotel/accommodation or service operator"],["int","Integrator oder Service-Plattform","Integrator or service platform"],["idps","Identität, Datenschutz oder Sicherheit (Verantwortung)","Identity, privacy or security owner"],["other","Andere","Other"]];
