/* ==========================================================================
   wallet.css — AskMI Wallet PWA UX Polish
   UX-01: CSS Classes replacing inline styles
   UX-02: State transitions & animations
   UX-03: Credential card design
   UX-04: Button hierarchy
   UX-05: Audit log
   UX-06: ConsentModal polish
   UX-07: GuidedDemo storytelling
   UX-08: Mobile polish
   ========================================================================== */

/* ── UX-01: Layout & Container ─────────────────────────────────────────── */

:root {
    --wallet-content-max: 860px;
    --wallet-column-max: 600px;
    --wallet-phone-max: 380px;
    --wallet-surface: rgba(255, 255, 255, 0.92);
    --wallet-surface-solid: #ffffff;
    --wallet-surface-muted: #f8fafc;
    --wallet-border: rgba(14, 165, 233, 0.18);
    --wallet-border-strong: rgba(14, 165, 233, 0.34);
    --wallet-text: #0f172a;
    --wallet-text-muted: #64748b;
    --wallet-accent: #0369a1;
    --wallet-accent-soft: #e0f2fe;
    --wallet-danger: #dc2626;
    --wallet-success: #047857;
    --wallet-warning: #92400e;
    --wallet-radius-sm: 8px;
    --wallet-radius-md: 12px;
    --wallet-radius-lg: 14px;
    --wallet-shadow-panel: 0 10px 26px rgba(15, 23, 42, 0.07);
}

.wallet-app {
    display: flex;
    flex-direction: column;
    align-items: center;
    width: 100%;
    min-height: 100vh;
    padding: 18px;
    padding-bottom: env(safe-area-inset-bottom, 20px);
    padding-top: env(safe-area-inset-top, 20px);
    box-sizing: border-box;
    overflow-x: hidden;
    background: linear-gradient(180deg, #ffffff 0%, #f4f7fb 100%);
    color: var(--wallet-text);
}

.wallet-title {
    margin: 0 0 4px;
    font-size: 22px;
    font-weight: 760;
    letter-spacing: 0;
}

.wallet-title-accent {
    font-weight: 800;
    color: #0070f3;
}

.wallet-subtitle {
    max-width: var(--wallet-content-max);
    margin: 0 auto 14px;
    color: var(--wallet-text-muted);
    font-size: 13px;
    line-height: 1.45;
    text-align: center;
}

.wallet-nav {
    position: sticky;
    top: max(8px, env(safe-area-inset-top, 8px));
    z-index: 20;
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    gap: 4px;
    width: 100%;
    max-width: var(--wallet-content-max);
    margin: 0 auto 16px;
    padding: 5px;
    border: 1px solid var(--wallet-border);
    border-radius: 999px;
    background: var(--wallet-surface);
    box-shadow: 0 8px 18px rgba(15, 23, 42, 0.07);
    backdrop-filter: blur(12px);
}

.wallet-nav button {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-height: 30px;
    padding: 0 9px;
    border: 0;
    border-radius: 999px;
    background: transparent;
    color: #075985;
    cursor: pointer;
    font-size: 11px;
    font-weight: 760;
    font: inherit;
    text-decoration: none;
    white-space: nowrap;
}

.wallet-nav button:hover,
.wallet-nav button:focus-visible,
.wallet-nav__item--active {
    background: var(--wallet-accent-soft);
    color: #0c4a6e;
    outline: none;
}

.wallet-section-rail {
    justify-content: space-between;
}

.wallet-overview {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 8px;
    width: 100%;
    max-width: var(--wallet-content-max);
    margin: 0 auto 16px;
}

.wallet-overview__item {
    min-width: 0;
    padding: 10px 12px;
    border: 1px solid var(--wallet-border);
    border-radius: var(--wallet-radius-md);
    background: var(--wallet-surface);
    box-shadow: 0 8px 18px rgba(15, 23, 42, 0.05);
    color: inherit;
}

