/* ── UX-08: Mobile / Responsive ──────────────────────────────────────────── */

@media (max-width: 480px) {
    .wallet-app {
        padding: 12px;
        padding-bottom: env(safe-area-inset-bottom, 12px);
    }

    .wallet-title {
        font-size: 21px;
    }

    .wallet-subtitle {
        margin-bottom: 10px;
        font-size: 12px;
    }

    .wallet-section-rail {
        position: sticky;
        top: max(8px, env(safe-area-inset-top, 8px));
        justify-content: space-between;
        width: 100%;
        max-width: var(--wallet-content-max);
        margin: 0 auto 12px;
        border-radius: 18px;
        box-shadow: 0 10px 24px rgba(15, 23, 42, 0.1);
    }

    .wallet-nav button {
        flex: 1 1 0;
        min-width: 0;
        padding: 0 4px;
        font-size: 10px;
    }

    .wallet-overview {
        grid-template-columns: repeat(3, minmax(0, 1fr));
        gap: 6px;
        margin-bottom: 14px;
    }

    .wallet-overview__item {
        padding: 9px 8px;
    }

    .wallet-overview__item span {
        font-size: 9px;
    }

    .wallet-overview__item strong {
        font-size: 11px;
    }

    .wallet-panel {
        padding: 14px;
@media (max-width: 860px) {
    .credential-card-list {
        grid-template-columns: 1fr;
    }

    .dev-tool-grid {
        grid-template-columns: 1fr;
    }
}

