}

.wallet-section {
    width: 100%;
    max-width: var(--wallet-column-max);
}

.wallet-panel {
    width: 100%;
    max-width: var(--wallet-content-max);
    box-sizing: border-box;
    margin: 0 auto 16px;
    padding: 16px;
    border: 1px solid var(--wallet-border);
    border-radius: var(--wallet-radius-lg);
    background: var(--wallet-surface);
    box-shadow: var(--wallet-shadow-panel);
}

.wallet-section-heading {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    gap: 12px;
    margin-bottom: 16px;
}

.wallet-section-heading p,
.wallet-section-heading h2 {
    margin: 0;
}

.wallet-section-heading p {
    color: var(--wallet-text-muted);
    font-size: 10px;
    font-weight: 800;
    letter-spacing: 0.06em;
    text-transform: uppercase;
}

.wallet-section-heading h2 {
    color: var(--wallet-text);
    font-size: 18px;
    font-weight: 850;
}

.wallet-section-heading span {
    flex-shrink: 0;
    padding: 4px 10px;
    border-radius: 999px;
    background: var(--wallet-accent-soft);
    color: var(--wallet-accent);
    font-size: 11px;
    font-weight: 800;
}

.wallet-flow-stack {
    display: flex;
    flex-direction: column;
    align-items: start;
    gap: 14px;
    width: 100%;
    max-width: var(--wallet-content-max);
    margin: 0 auto 16px;
}

.wallet-flow-stack .audit-section {
    margin: 0 auto;
}

/* ── UX-03: Credential Card ─────────────────────────────────────────────── */

.credential-card {
    position: relative;
    width: 100%;
    max-width: var(--wallet-phone-max);
    margin-bottom: 0;
    padding: 20px;
    background: linear-gradient(135deg, #1a1a2e 0%, #16213e 50%, #0f3460 100%);
    border-radius: 20px;
    border: 1px solid rgba(0, 191, 255, 0.2);
    border: 1px solid var(--wallet-border);
    box-shadow: var(--wallet-shadow-panel);
    box-sizing: border-box;
}

.scenario-launcher {
    min-height: 100%;
}

.advanced-section {
    width: 100%;
    max-width: 100%;
    margin-bottom: 0;
}

.wallet-tools-page {
    width: 100%;
    max-width: var(--wallet-column-max);
    display: flex;
    flex-direction: column;
    gap: 16px;
}

.wallet-tools-panel {
    gap: 16px;
}

.scenario-launcher__header {
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    gap: 12px;
    margin-bottom: 14px;
}

.scenario-launcher__header .demo-section-title {
    margin-bottom: 0;
}

.scenario-launcher__hint {
    color: #64748b;
    font-size: 12px;
    font-weight: 600;
}

.scenario-launcher__grid {
    margin-bottom: 0;
}

.demo-section-title {
    margin: 0 0 16px 0;
    font-size: 16px;
    color: #0f172a;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    font-weight: 800;
}

.demo-primary-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 10px;
    margin-bottom: 12px;
}

.btn-demo-primary {
    padding: 14px 12px;
    border-radius: 10px;
    border: 1px solid rgba(14, 165, 233, 0.2);
    color: #0f172a;
    font-size: 13px;
    font-weight: 700;
    cursor: pointer;
    transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
    line-height: 1.4;
    text-align: left;
    min-height: 44px;
    position: relative;
    overflow: hidden;
    background: rgba(255, 255, 255, 0.82);
}

.btn-demo-primary::after {
    content: '';
    position: absolute;
    inset: 0;
    background: rgba(255,255,255,0);
    transition: background 0.15s;
}

.btn-demo-primary:hover:not(:disabled)::after {
    background: rgba(14, 165, 233, 0.08);
}

.btn-demo-primary:active:not(:disabled) {
    transform: scale(0.96);
}

.btn-demo-primary:focus-visible {
    outline: 2px solid var(--accent-blue);
    outline-offset: 2px;
}

.btn-demo-primary:disabled {
    opacity: 0.45;
    cursor: not-allowed;
    filter: grayscale(40%);
}

.btn-scenario-card {
