    create: async () => ({
      rawId,
      response: {
        getPublicKey: () => (opts.exposePublicKey === false ? null : pair.spki),
        getPublicKeyAlgorithm: () => -7,
      },
    }),
    get: async ({ publicKey }: { publicKey: PublicKeyCredentialRequestOptions }) => {
