        rawId,
        response: {
          authenticatorData: parts.authenticatorData.buffer,
          clientDataJSON: parts.clientDataJSON.buffer,
          signature: parts.signature.buffer,
        },
      };
    },
  };
  return { ...pair, credentials };
}

