      verifier_id: verifierId,
      reason,
      endpoint: reportEndpoint,
      status: 'SENT',
      proof_token: proofToken,
    });

    return {
      success: true,
      message: `Report for ${verifierId} has been submitted to the authorities.`,
    };
  }

