async (page) => {
  await page.getByRole('button', { name: /Create my AskMI account/i }).click();
  await page.waitForTimeout(3000);
  const stored = await page.evaluate(() => new Promise((resolve) => {
    const open = indexedDB.open('askmi_passkey_db', 1);
    open.onsuccess = () => {
      const tx = open.result.transaction('passkeys', 'readonly');
      const req = tx.objectStore('passkeys').get('askmi_identity_key_registration');
      req.onsuccess = () => { const m = req.result ? JSON.parse(req.result) : null; resolve(m && { rpId: m.rpId, kty: m.publicKeyJwk?.kty, crv: m.publicKeyJwk?.crv, hasX: !!m.publicKeyJwk?.x, hasY: !!m.publicKeyJwk?.y }); };
      req.onerror = () => resolve('err');
    };
    open.onerror = () => resolve('open-err');
  }));
  const status = await page.locator('.wallet-overview').innerText().catch(() => 'no overview');
  return { stored, status: status.replace(/\s+/g, ' ') };
}

