        store.put(JSON.stringify(m), 'askmi_identity_key_registration');
      };
      tx.oncomplete = () => resolve('ok');
    };
  }));
  await page.reload();
  await page.waitForTimeout(2500);
  const unlock = page.getByRole('button', { name: /unlock/i }).first();
  if (await unlock.isVisible().catch(() => false)) { await unlock.click(); await page.waitForTimeout(2500); }
  const prompt = page.getByRole('region', { name: /passkey/i });
  const promptVisible = await prompt.isVisible().catch(() => false);
  await page.screenshot({ path: '.playwright-mcp/pr3-prompt.png' });
  const nav = page.getByRole('navigation', { name: /wallet sections/i });
  await nav.getByRole('button', { name: 'Requests' }).click();
  await page.locator('#btn-liquor-store').click();
  await page.waitForTimeout(5000);
  await nav.getByRole('button', { name: 'Audit' }).click();
  const lines = (await page.locator('body').innerText()).split('\n').filter((l) => /Capsule|ALERT|not verifiable/i.test(l));
