async (page) => {
  const errors = [];
  page.on('pageerror', e => errors.push('pageerror: ' + e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
  const cdp = await page.context().newCDPSession(page);
  await cdp.send('WebAuthn.enable');
  await cdp.send('WebAuthn.addVirtualAuthenticator', { options: { protocol: 'ctap2', transport: 'internal', hasResidentKey: true, hasUserVerification: true, isUserVerified: true, automaticPresenceSimulation: true } });
  await page.goto('http://localhost:5184/');
  await page.evaluate(async () => { localStorage.clear(); const dbs = await indexedDB.databases(); for (const d of dbs) indexedDB.deleteDatabase(d.name); });
  await page.reload();
  await page.getByRole('button', { name: /Create my AskMI account/i }).click({ timeout: 15000 });
  await page.waitForTimeout(2500);
  const tabs = await page.locator('.wallet-nav button').allInnerTexts();
  await page.getByRole('button', { name: /Requests/ }).first().click();
  await page.getByRole('button', { name: /Prove Age/i }).first().click();
  await page.waitForTimeout(4000);
  await page.getByRole('button', { name: /^Audit/ }).first().click();
  await page.waitForTimeout(800);
  const body = await page.locator('body').innerText();
  const lines = body.split('\n').filter(l => /Capsule|SECURITY|verifiable|Verified|Presentation/i.test(l)).slice(0, 12);
  return { tabs, lines, errors };
}

