async (page) => {
  const errors = []; const notFound = [];
  page.on('pageerror', e => errors.push('pageerror: ' + e.message.slice(0, 100)));
  page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text().slice(0, 120)); });
  page.on('response', r => { if (r.status() === 404) notFound.push(r.url()); });
  await page.goto('http://localhost:5186/');
  await page.waitForTimeout(2500);
  const text = (await page.locator('body').innerText()).slice(0, 200);
  const svgs = await page.locator('svg').count();
  const scen = await page.getByRole('button').allInnerTexts();
  await page.screenshot({ path: '.playwright-mcp/vite8-verifier-fixed.png' });
  return { text, svgs, scenarios: scen.slice(0, 8), notFound, errors };
}

