async (page) => {
  await page.addInitScript(() => {
    window.__qrSeen = null;
    new MutationObserver(() => {
      const s = document.querySelector('svg');
      if (s && !window.__qrSeen) window.__qrSeen = { paths: s.querySelectorAll('path').length, w: s.getAttribute('width') || s.getAttribute('viewBox'), d: (s.querySelector('path:last-child')?.getAttribute('d') || '').length };
    }).observe(document, { subtree: true, childList: true });
  });
  await page.goto('http://localhost:5186/');
  await page.waitForTimeout(2500);
  const seen = await page.evaluate(() => window.__qrSeen);
  const panel = (await page.locator('body').innerText()).split('\n').filter(l => /QR|wallet|Waiting|error|unreach|backend/i.test(l)).slice(0, 6);
  return { seen, panel };
}

